class NamedNamingTests(unittest.TestCase):
 def fixture(self):
  f=copy.deepcopy(FIXTURE);p=f['paragraph'];c=f['holding']['evidence'][0]['chapter_id'];return f,{p['id']:(c,p)},{m['id']:(c,p['id'],m) for m in p['mentions']},{f['death']['id']:f['death']}
 def test_full_note_positive_unknown_year(self):
  f,p,m,d=self.fixture();self.assertTrue(valid(f['holding'],p,m,d));self.assertIsNone(f['death']['date_expression']);self.assertEqual(f['holding']['title'],'𤣥行先生')
 def test_same_death_may_have_other_primary_term(self):
  f,p,m,d=self.fixture();f['death']['source_term']='年五十而終';self.assertTrue(valid(f['holding'],p,m,d))
 def test_rejections(self):
  cases={
   'issuer_not_recipient':lambda f:f['holding'].update(person_id='jef_b3o_60j'),
   'wrong_death_person':lambda f:f['death'].update(person_id='jef_b3o_60j'),
   'wrong_death_event':lambda f:f['holding']['naming_basis'].update(death_event_id='missing'),
   'wrong_death_subject':lambda f:f['holding']['naming_basis'].update(death_subject_mention_id=f['paragraph']['id']+':m0046'),
   'wrong_recipient':lambda f:f['holding']['naming_basis'].update(recipient_person_mention_id=f['paragraph']['id']+':m0061'),
   'wrong_issuer':lambda f:f['holding']['naming_basis'].update(issuer_person_mention_id=f['paragraph']['id']+':m0050'),
   'wrong_title_glyph':lambda f:f['holding'].update(title='玄行先生'),
   'wrong_death_offset':lambda f:f['holding']['naming_basis']['death_anchor'].update(start=53),
   'wrong_title_offset':lambda f:f['holding']['attestations'][0].update(start=75),
   'wrong_naming_offset':lambda f:f['holding']['naming_basis']['naming_anchor'].update(start=71),
   'wrong_source_version':lambda f:f['death']['evidence'][0].update(source_id='another-source'),
   'missing_same_note_death':lambda f:f['death'].update(evidence=[]),
   'not_dead':lambda f:f['death'].update(event_type='appointment'),
   'ordinary_role':lambda f:f['holding'].update(mode='attestation'),
   'wrong_attestation_person':lambda f:f['holding']['attestations'][0].update(person_mention_id=f['paragraph']['id']+':m0070'),
   'partial_quote':lambda f:f['holding']['naming_basis'].update(source_term='追號靖曰𤣥行先生')}
  for label,change in cases.items():
   with self.subTest(label=label):
    f,p,m,d=self.fixture();change(f);self.assertFalse(valid(f['holding'],p,m,d))
 def test_plain_hao_not_accepted(self):
  f,p,m,d=self.fixture()
  text=f['paragraph']['text'].replace('追號','自號')
  f['paragraph']['text']=text;f['holding']['naming_basis']['source_term']=text
  f['holding']['naming_basis']['naming_anchor']['surface']='自號靖曰𤣥行先生'
  for e in f['holding']['evidence']+f['holding']['effective_period']['start']['evidence']+f['holding']['naming_basis']['evidence']+f['death']['evidence']:e['quote']=text
  self.assertFalse(valid(f['holding'],p,m,d))
if __name__=='__main__':unittest.main()
